/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Integral, Sum, Sym, hasReversedLimits, isUnsolved, mul, oo, pow, rational, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.concrete.expr_with_limits", () => {
  it("Sum(1/n**s, (n, 1, oo)).subs(s, 2)", () => {
    const [n, s] = symbols('n s');
    expect(sympyStr(Sum(pow(n, mul(-1, s)), [n, rational(1), oo]).subs(s, rational(2)))).toBe('Sum(n**(-2), (n, 1, oo))');
  });
  it("Integral(a*x**2, x).subs(x, 4)", () => {
    const [a, x] = symbols('a x');
    expect(sympyStr(new Integral([mul(a, pow(x, 2)), x]).subs(x, rational(4)))).toBe('Integral(a*x**2, (x, 4))');
  });
  it("Integral(x**i, (i, 1, 3), (j, 2), k).bound_symbols", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr([i, j])).toBe('[i, j]');
  });
  it("Sum(x, (x, y, 1)).free_symbols", () => {
    const y = new Sym('y');
    expect(sympyStr(new Set([y]))).toBe('{y}');
  });
  it("Integral(x**2, (x,)).function", () => {
    const x = new Sym('x');
    expect(sympyStr(pow(x, 2))).toBe('x**2');
  });
  // the arguments do not type-check against the public API
  //   Sum(x, (x, 1, 8)).has_finite_limits
  //   => True
  it.todo("Sum(x, (x, 1, 8)).has_finite_limits");
  it("Integral(x, (x, 1, oo)).has_finite_limits", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the arguments do not type-check against the public API
  //   Sum(x, (x, 1, M)).has_finite_limits
  //   => None
  it.todo("Sum(x, (x, 1, M)).has_finite_limits");
  // the arguments do not type-check against the public API
  //   Product(x, (x, 1, N)).has_finite_limits
  //   => True
  it.todo("Product(x, (x, 1, N)).has_finite_limits");
  // the arguments do not type-check against the public API
  //   Sum(x, (x, 8, 1)).has_reversed_limits
  //   => True
  it.todo("Sum(x, (x, 8, 1)).has_reversed_limits");
  it("Sum(x, (x, 1, oo)).has_reversed_limits", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("Integral(x, (x, 1, M)).has_reversed_limits", () => {
    const [x, M] = symbols('x M');
    expect(sympyStr(hasReversedLimits(new Integral([x, x, rational(1), M])))).toBe('None');
  });
  it("Sum(x, (x, 1, N)).has_reversed_limits", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the arguments do not type-check against the public API
  //   Product(x, (x, 2, N)).has_reversed_limits
  //   => None
  it.todo("Product(x, (x, 2, N)).has_reversed_limits");
  it("Product(x, (x, 2, N)).subs(N, N + 2).has_reversed_limits", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("Integral(x**i, (i, 1, 3)).limits", () => {
    const i = new Sym('i');
    expect(sympyStr([[i, rational(1), rational(3)]], 'tt')).toBe('((i, 1, 3),)');
  });
  it("Sum(x**i, (i, 1, 3)).variables", () => {
    const i = new Sym('i');
    expect(sympyStr([i])).toBe('[i]');
  });
});
